const D=window.RADAR,app=document.querySelector("#app"),TODAY=new Date();
// Estado editorial pessoal — Supabase
const SUPABASE_URL="https://uzqwhdtvoysxweuyvnup.supabase.co",SUPABASE_KEY="sb_publishable_z64gznAmfuqD9zByxE35AQ_kqqKsg9f";
let SB=null,EDITORIAL={user:null,states:new Map(),ready:false};
const stateKey=(type,id)=>type+":"+id;
const stateLabels={
 opportunity:{vou_fazer:"Vou fazer",em_andamento:"Em andamento",sem_interesse:"Não agora",pausado:"Pausado",concluido:"Concluído"},
 story:{avaliar:"Pré-apuração",vou_fazer:"Em andamento",submetida:"Submetida",aceita:"Aceita",em_andamento:"Em produção",pausado:"Pausada",concluido:"Publicada",sem_interesse:"Arquivada"},
 dataset:{vou_fazer:"Salva",em_andamento:"Em uso",concluido:"Já usei",sem_interesse:"Oculta"}
};
function editorialState(type,id){return EDITORIAL.states.get(stateKey(type,id))||null}
function labelState(type,state){let submission={submetida:"Submetida",aceita:"Aceita",rejeitada:"Rejeitada"};return type==="submission"?(submission[state]||state):stateLabels[type]?.[state]||state?.replaceAll("_"," ")||""}
function stateMark(type,id){let x=editorialState(type,id);return x?'<span class="estate '+type+'-state '+x.state+'"><i></i>'+labelState(type,x.state)+'</span>':""}
function stateOptions(type,current){let labels=stateLabels[type]||stateLabels.opportunity;return '<option value="">'+(type==="opportunity"?"Para decidir":type==="story"?"Sem etapa pessoal":"Não salva")+'</option>'+Object.entries(labels).map(([k,l])=>'<option value="'+k+'" '+(current===k?"selected":"")+'>'+l+'</option>').join("")}
function stateControl(type,id){let x=editorialState(type,id),v=x?.state||"";if(!EDITORIAL.user)return'<div class="estatebox"><b>Estado pessoal</b><span class="meta">Entre no Radar para sincronizar decisões e notas.</span><button class="btn" onclick="loginRadar()">Entrar por e-mail</button></div>';return'<div class="estatebox"><b>Estado pessoal</b><select onchange="saveEditorialState(\''+type+'\',\''+id+'\',this.value)">'+stateOptions(type,v)+'</select><textarea id="estate-note" placeholder="Nota pessoal (opcional)">'+(x?.note||"")+'</textarea><button class="btn" onclick="saveEditorialState(\''+type+'\',\''+id+'\',document.querySelector(\'.estatebox select\').value,document.querySelector(\'#estate-note\').value)">Salvar nota</button><span id="estate-save" class="meta"></span></div>'}
function quickState(type,id,state,event){if(event){event.preventDefault();event.stopPropagation()}return saveEditorialState(type,id,state)}
function quickActions(o){if(!EDITORIAL.user)return"";let st=editorialState("opportunity",o.id)?.state;return'<div class="quickactions" onclick="event.stopPropagation()">'+(st!=="vou_fazer"?'<button onclick="quickState(\'opportunity\',\''+o.id+'\',\'vou_fazer\',event)">Vou fazer</button>':"")+(st!=="sem_interesse"?'<button onclick="quickState(\'opportunity\',\''+o.id+'\',\'sem_interesse\',event)">Não agora</button>':"")+'</div>'}
function storySubmissions(id){return[...EDITORIAL.states.values()].filter(x=>x.record_type==="submission"&&submissionData(x)?.storyId===id).sort((a,b)=>(submissionData(b)?.date||"").localeCompare(submissionData(a)?.date||""))}
function submissionData(x){try{return JSON.parse(x?.note||"{}")}catch{return{}}}
function submissionHistory(id){let rows=storySubmissions(id);return '<div class="submissionbox"><h3>Submissões</h3><p class="meta">O histórico permanece salvo mesmo se a pauta voltar para “Em andamento”.</p>'+(EDITORIAL.user?'<div class="submissionform"><input id="submission-destination" placeholder="Veículo, edital, grant ou programa"><input id="submission-date" type="date" value="'+new Date().toISOString().slice(0,10)+'"><button class="btn" onclick="addSubmission(\''+id+'\')">Registrar submissão</button></div>':'')+(rows.length?'<div class="submissionhistory">'+rows.map(x=>{let d=submissionData(x);return'<div class="submissionrow"><div><b>'+d.destination+'</b><div class="meta">'+fmt(d.date)+' · '+labelState("submission",x.state)+'</div></div><div>'+(x.state==="submetida"?'<button class="btn" onclick="resolveSubmission(\''+x.record_id+'\',\'aceita\')">Aceita</button><button class="btn" onclick="resolveSubmission(\''+x.record_id+'\',\'rejeitada\')">Rejeitada</button>':"")+'</div></div>'}).join("")+'</div>':'<p class="meta">Nenhuma submissão registrada.</p>')+'</div>'}
async function addSubmission(storyId){if(!SB||!EDITORIAL.user)return loginRadar();let dest=document.querySelector("#submission-destination")?.value.trim(),date=document.querySelector("#submission-date")?.value;if(!dest)return alert("Informe para onde a pauta foi submetida.");let id=storyId+"--"+Date.now(),payload={user_id:EDITORIAL.user.id,record_id:id,record_type:"submission",state:"submetida",note:JSON.stringify({storyId,destination:dest,date:date||new Date().toISOString().slice(0,10)})};setSync("saving");let {data,error}=await SB.from("editorial_state").upsert(payload,{onConflict:"user_id,record_type,record_id"}).select().single();if(error){setSync("error");return alert("Não foi possível registrar a submissão: "+error.message)}EDITORIAL.states.set(stateKey("submission",id),data);await saveEditorialState("story",storyId,"submetida");}
async function resolveSubmission(id,result){let x=editorialState("submission",id);if(!x||!SB||!EDITORIAL.user)return;let d=submissionData(x);d.resultDate=new Date().toISOString().slice(0,10);setSync("saving");let payload={user_id:EDITORIAL.user.id,record_id:id,record_type:"submission",state:result,note:JSON.stringify(d)},{data,error}=await SB.from("editorial_state").upsert(payload,{onConflict:"user_id,record_type,record_id"}).select().single();if(error){setSync("error");return alert("Não foi possível atualizar a submissão: "+error.message)}EDITORIAL.states.set(stateKey("submission",id),data);await saveEditorialState("story",d.storyId,result==="aceita"?"aceita":"vou_fazer");}
async function loginRadar(){if(!SB)return alert("Sincronização ainda carregando.");let email=prompt("E-mail para receber o link de acesso ao Radar:");if(!email)return;let {error}=await SB.auth.signInWithOtp({email,options:{emailRedirectTo:"https://r4chelxx.github.io/radar-plot-grants-fellowships/"}});alert(error?"Não foi possível enviar o link: "+error.message:"Link de acesso enviado. Abra o e-mail neste dispositivo.")}
async function logoutRadar(){if(SB)await SB.auth.signOut();EDITORIAL.user=null;EDITORIAL.states.clear();EDITORIAL.ready=false;render();renderAuth()}
async function loadEditorial(){if(!SB||!EDITORIAL.user)return;setSync("loading");let {data,error}=await SB.from("editorial_state").select("record_id,record_type,state,note,updated_at");if(error){console.error("Radar state",error);setSync("error");return}EDITORIAL.states=new Map((data||[]).map(x=>[stateKey(x.record_type,x.record_id),x]));EDITORIAL.ready=true;setSync("ok");render()}
async function saveEditorialState(type,id,state,note){if(!SB||!EDITORIAL.user)return loginRadar();setSync("saving");let current=editorialState(type,id);if(!state){let {error}=await SB.from("editorial_state").delete().eq("user_id",EDITORIAL.user.id).eq("record_type",type).eq("record_id",id);if(error){setSync("error");return alert("Não foi possível salvar: "+error.message)}EDITORIAL.states.delete(stateKey(type,id));setSync("ok");render();return}let payload={user_id:EDITORIAL.user.id,record_id:id,record_type:type,state,note:note!==undefined?note:(current?.note||null)};let {data,error}=await SB.from("editorial_state").upsert(payload,{onConflict:"user_id,record_type,record_id"}).select().single();if(error){setSync("error");return alert("Não foi possível salvar: "+error.message)}EDITORIAL.states.set(stateKey(type,id),data);setSync("ok");render();let msg=document.querySelector("#estate-save");if(msg){msg.textContent="Salvo ✓";setTimeout(()=>{if(msg)msg.textContent=""},1600)}}
function setSync(status){EDITORIAL.sync=status;renderAuth()}
function renderAuth(){let el=document.querySelector("#auth");if(!el)return;if(!EDITORIAL.user){el.innerHTML='<button onclick="loginRadar()">Entrar</button>';return}let s=EDITORIAL.sync==="saving"||EDITORIAL.sync==="loading"?"Salvando…":EDITORIAL.sync==="error"?"Não sincronizado":"Sincronizado";el.innerHTML='<span class="syncdot '+(EDITORIAL.sync==="error"?"syncerror":EDITORIAL.sync==="saving"||EDITORIAL.sync==="loading"?"syncbusy":"")+'"></span><span>'+s+'</span><button onclick="logoutRadar()">Sair</button>'}
async function initEditorial(){if(!window.supabase){renderAuth();return}SB=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);let {data:{session}}=await SB.auth.getSession();EDITORIAL.user=session?.user||null;renderAuth();if(EDITORIAL.user)await loadEditorial();SB.auth.onAuthStateChange(async(_,session)=>{EDITORIAL.user=session?.user||null;renderAuth();if(EDITORIAL.user)await loadEditorial();else{EDITORIAL.states.clear();EDITORIAL.ready=false;render()}})}

const fmt=d=>d?new Intl.DateTimeFormat("pt-BR").format(new Date(d+"T12:00:00")):"—",opp=id=>D.opportunities.find(x=>x.id===id),story=id=>D.stories.find(x=>x.id===id),route=()=>location.hash.slice(1)||"visao";
const days=(a,b=TODAY)=>Math.round((new Date(a+"T12:00:00")-b)/864e5),age=o=>o.verified?Math.max(0,-days(o.verified)):null;
function action(o){if(["encerrada","descartada"].includes(o.status)||o.eligibility==="inelegível")return"nenhuma ação";if(o.eligibility==="parcial")return"buscar parceria";if(o.eligibility==="verificar")return"pendente de confirmação";if(o.status==="preparar")return"preparar";if(o.status==="monitorar")return"monitorar";if(o.deadlineStatus?.includes("futura")||o.deadlineStatus?.includes("abre_"))return"aguardar abertura";return"avaliar/aplicar"}
function readiness(o){if(o.eligibility==="inelegível"||["encerrada","descartada"].includes(o.status))return"fora do pipeline";if(o.eligibility==="verificar"||o.eligibility==="parcial")return"baixa";if(o.status==="preparar")return"média";if(o.status==="aberta"&&o.fit>=9)return"alta";return"média"}
function nextStep(o){if(o.eligibility==="inelegível")return"Sem ação: inelegível.";if(["encerrada","descartada"].includes(o.status))return"Monitorar apenas nova edição, se pertinente.";if(o.eligibility==="parcial")return"Identificar parceria que satisfaça as regras antes de adaptar qualquer pauta.";if(o.eligibility==="verificar")return"Há requisito de elegibilidade ainda não confirmado na fonte oficial.";if(o.opens&&days(o.opens)>0)return"Preparar materiais antes da abertura em "+fmt(o.opens)+".";if(o.deadline&&days(o.deadline)>=0&&days(o.deadline)<=14)return"Decidir candidatura e fechar documentos antes de "+fmt(o.deadline)+".";if(o.documents?.length)return"Revisar e preparar: "+o.documents.join(", ")+".";if(o.deadlineStatus==="rolling")return"Avaliar encaixe de uma pauta madura; não adaptar artificialmente.";return"Rever fonte oficial e decidir se entra no pipeline."}
function badge(x,link=true){let v=String(x||"").replaceAll("_"," "),attr=' class="badge" data-theme="'+v.toLowerCase()+'"';return link?'<a'+attr+' href="#tema/'+encodeURIComponent(v)+'" onclick="event.stopPropagation()">'+v+'</a>':'<span'+attr+'>'+v+'</span>'}
function nav(){document.querySelectorAll("nav a").forEach(a=>a.classList.toggle("active",a.getAttribute("href")==="#"+route().split("/")[0]))}
function head(k,t,l){return'<div class="eyebrow">'+k+'</div><h1>'+t+'</h1><p class="lede">'+l+'</p>'}
function freshness(o){let a=age(o);return a==null?"não verificado":a===0?"verificado hoje":a===1?"verificado há 1 dia":"verificado há "+a+" dias"}
function shortDesc(o){let s=(o.summary||o.desc||"").trim();if(!s)return"";let first=s.split(/(?<=[.!?])\s+/)[0];return first.length>150?first.slice(0,147).trim()+"…":first}
function orow(o){return'<div class="row clickable" onclick="location.hash=\'oportunidade/'+o.id+'\'"><div><div class="org">'+o.org+'</div><h3>'+o.title+' '+stateMark("opportunity",o.id)+'</h3><p class="oppsummary">'+shortDesc(o)+'</p>'+o.themes.map(x=>badge(x)).join("")+quickActions(o)+'</div><div><div class="meta">'+(o.deadline?fmt(o.deadline):o.deadlineStatus==="rolling"?"Fluxo contínuo":"Sem data confirmada")+'</div></div><div><span class="score">'+o.fit+'</span><span class="meta"> / 10</span></div><div>'+badge(o.eligibility,false)+'</div></div>'}
function home(){let active=D.opportunities.filter(o=>!["encerrada","descartada"].includes(o.status)&&o.eligibility!=="inelegível"&&editorialState("opportunity",o.id)?.state!=="sem_interesse"),undecided=active.filter(o=>!editorialState("opportunity",o.id)),selected=active.filter(o=>editorialState("opportunity",o.id)?.state==="vou_fazer"),working=active.filter(o=>editorialState("opportunity",o.id)?.state==="em_andamento"),personal=[...selected,...working],soon=active.filter(o=>o.deadline&&days(o.deadline)>=0&&days(o.deadline)<=30),news=(D.changelog||[]).filter(x=>x.type==="nova-oportunidade"&&days(x.date)>=-7).sort((a,b)=>b.date.localeCompare(a.date)),activeStories=D.stories.filter(s=>["vou_fazer","em_andamento","submetida","aceita"].includes(editorialState("story",s.id)?.state));return head("Inteligência editorial","Radar PLOT<span class='accent'>.</span>","O que merece atenção agora: decisões, trabalho ativo e prazos do PLOT.")+'<div class="metrics"><a class="metric metriclink" href="#oportunidades/decidir"><b>'+undecided.length+'</b><span>para decidir</span></a><a class="metric metriclink" href="#oportunidades/preparar"><b>'+selected.length+'</b><span>em preparação</span></a><a class="metric metriclink" href="#oportunidades/andamento"><b>'+working.length+'</b><span>em andamento</span></a><a class="metric metriclink" href="#oportunidades/prazo30"><b>'+soon.length+'</b><span>prazos em 30 dias</span></a></div>'+(working.length||activeStories.length?'<h2>Em andamento</h2><div class="workgrid">'+working.map(o=>'<a class="workitem" href="#oportunidade/'+o.id+'"><div class="eyebrow">Candidatura</div><h3>'+o.title+'</h3>'+stateMark("opportunity",o.id)+'</a>').join("")+activeStories.map(s=>'<a class="workitem" href="#pauta/'+s.id+'"><div class="eyebrow">Pauta</div><h3>'+s.title+'</h3>'+stateMark("story",s.id)+'</a>').join("")+'</div>':"")+(news.length?'<h2>Novas oportunidades</h2><div class="timeline">'+news.slice(0,6).map(x=>{let o=D.opportunities.find(o=>o.title===x.title);return'<div class="event"><b>'+fmt(x.date)+'</b> · '+(o?'<a href="#oportunidade/'+o.id+'">'+x.title+'</a>':x.title)+'<div class="meta">'+x.detail+'</div>'+(o?quickActions(o):"")+'</div>'}).join("")+'</div>':"")+'<h2>Para decidir</h2>'+(undecided.length?'<div class="list">'+undecided.sort((a,b)=>(a.deadline||"9999").localeCompare(b.deadline||"9999")).slice(0,8).map(orow).join("")+'</div>':'<div class="warning ok"><b>Triagem em dia:</b> nenhuma oportunidade ativa aguarda sua decisão.</div>')+'<h2>Meus próximos prazos</h2>'+(personal.filter(o=>o.deadline&&days(o.deadline)>=0).length?'<div class="timeline">'+personal.filter(o=>o.deadline&&days(o.deadline)>=0).sort((a,b)=>a.deadline.localeCompare(b.deadline)).slice(0,10).map(o=>'<div class="event"><b>'+fmt(o.deadline)+'</b> · <a href="#oportunidade/'+o.id+'">'+o.title+'</a> '+stateMark("opportunity",o.id)+'<div class="meta">'+o.org+'</div></div>').join("")+'</div>':'<p class="meta">Nenhum prazo pessoal selecionado.</p>')}
function download(name,type,content){let b=new Blob([content],{type}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function exportJSON(){download("radar-plot-oportunidades.json","application/json",JSON.stringify(D.opportunities,null,2))}
function exportCSV(){let cols=["title","org","type","scope","deadline","eligibility","fit","status","verified"],esc=v=>'"'+String(v??"").replaceAll('"','""')+'"';download("radar-plot-oportunidades.csv","text/csv;charset=utf-8","\ufeff"+cols.join(",")+"\n"+D.opportunities.map(o=>cols.map(k=>esc(o[k])).join(",")).join("\n"))}
function exportICS(){let ev=D.opportunities.filter(o=>o.deadline&&!["encerrada","descartada"].includes(o.status)).map(o=>"BEGIN:VEVENT\nDTSTART;VALUE=DATE:"+o.deadline.replaceAll("-","")+"\nSUMMARY:"+o.title.replaceAll(",","\\,")+" — Radar PLOT.\nDESCRIPTION:"+o.org.replaceAll(",","\\,")+"\nURL:"+o.rules+"\nEND:VEVENT").join("\n");download("radar-plot-prazos.ics","text/calendar","BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//PLOT//Radar//PT-BR\n"+ev+"\nEND:VCALENDAR")}
function opportunities(){let themes=[...new Set(D.opportunities.flatMap(o=>o.themes))].sort();return head("Radar","Oportunidades","Filtre por elegibilidade, ação, pauta, tema e tipo. Aderência, elegibilidade e prontidão são dimensões independentes.")+'<div class="exports"><button class="btn" onclick="exportCSV()">Exportar CSV</button><button class="btn" onclick="exportJSON()">Exportar JSON</button><button class="btn" onclick="exportICS()">Exportar prazos .ICS</button></div><div class="toolbar"><input id="q" placeholder="Buscar título, organização, tema ou pauta"><select id="type"><option value="">Todos os tipos</option>'+[...new Set(D.opportunities.map(o=>o.type))].sort().map(x=>"<option>"+x+"</option>").join("")+'</select><select id="elig"><option value="">Elegibilidade</option><option>elegível</option><option>verificar</option><option>parcial</option></select><select id="personal"><option value="">Estado pessoal</option><option value="decidir">Para decidir</option><option value="vou_fazer">Vou fazer</option><option value="em_andamento">Em andamento</option><option value="pausado">Pausado</option><option value="concluido">Concluído</option><option value="sem_interesse">Não agora</option></select><select id="act"><option value="">Recomendação do Radar</option>'+[...new Set(D.opportunities.map(action))].sort().map(x=>"<option>"+x+"</option>").join("")+'</select><select id="theme"><option value="">Tema</option>'+themes.map(x=>"<option>"+x+"</option>").join("")+'</select><select id="sort"><option value="deadline">Prazo</option><option value="fit">Aderência</option><option value="fresh">Verificação</option></select></div><div id="olist" class="list"></div>'}
function stories(full=true){let cards='<div class="grid">'+D.stories.map(s=>'<article class="card" onclick="location.hash=\'pauta/'+s.id+'\'"><div class="eyebrow">'+s.status+'</div><h3>'+s.title+' '+stateMark("story",s.id)+'</h3><p>'+s.summary+'</p>'+s.themes.slice(0,5).map(x=>badge(x)).join("")+'</article>').join("")+'</div>';return full?head("Projetos","Pautas PLOT.","Investigações, propostas e experimentos editoriais relacionados às oportunidades e bases do Radar.")+ '<div class="exports"><a class="btn" href="#matriz">Abrir matriz pauta × oportunidade</a></div>'+cards:cards}
function dataQuestion(d){let n=(d.name+" "+d.themes.join(" ")).toLowerCase();if(n.includes("mortal")||n.includes("ouvidor"))return"Ajuda a dimensionar ocorrência, distribuição e padrões territoriais/temporais relevantes à pauta.";if(n.includes("cnes")||n.includes("estabelecimento"))return"Ajuda a localizar serviços, estabelecimentos e capacidade instalada no território.";if(n.includes("sisagua")||n.includes("captação"))return"Ajuda a mapear captação e contexto hídrico associado à infraestrutura.";if(n.includes("energia")||n.includes("aneel")||n.includes("dec")||n.includes("fec"))return"Ajuda a testar padrões de infraestrutura, continuidade e ocorrências elétricas sem presumir causalidade.";if(n.includes("educa")||n.includes("sidra"))return"Ajuda a cruzar território, características educacionais e desigualdades.";return"Base de apoio para cruzamentos, contextualização e teste de hipóteses."}
function datasetMeta(d){return{period:d.period||null,granularity:d.granularity||null,geoUnit:d.geoUnit||null,api:d.api??(/api/i.test(d.format||"")?"indicada":"não informada"),docs:d.docs||null,limitations:d.limitations||null,lastChecked:d.lastChecked||null}}
function datasetCompleteness(d){let m=datasetMeta(d),byKind={dataset:[d.coverage,d.frequency,d.format,d.url,m.period,m.granularity,m.geoUnit,m.docs,m.lastChecked],system:[d.coverage,d.frequency,d.format,d.url,m.docs,m.lastChecked],portal:[d.coverage,d.format,d.url,m.docs,m.lastChecked,m.limitations],catalog:[d.coverage,d.format,d.url,m.docs,m.lastChecked,m.limitations],"curated-source":[d.coverage,d.frequency,d.format,d.url,m.docs,m.lastChecked,m.limitations]},fields=byKind[d.kind]||byKind.dataset;return Math.round(fields.filter(Boolean).length/fields.length*100)}
function datasetKind(d){return({dataset:"Conjunto de dados",portal:"Portal de descoberta",catalog:"Catálogo de dados",system:"Sistema de dados","curated-source":"Fonte temática curada"}[d.kind]||"Conjunto de dados")}
function datasetPurposes(d){let s=[d.name,d.org,d.coverage,d.format,...(d.themes||[])].join(" ").toLowerCase(),p=[];const add=(x)=>{if(!p.includes(x))p.push(x)};if(/contrat|licita|pagamento|nfe|nota fiscal|convênio|compras|transparência|gastos/.test(s))add("Seguir dinheiro");if(/gis|cartograf|território|geograf|map|localidade|imóve|bairro|municip|geo/.test(s))add("Mapear território");if(/empresa|fornecedor|cnpj|negócio|estabelecimento/.test(s))add("Identificar empresas e atores");if(/saúde|mortal|nascid|sinasc|sih|cnes|obstetr|neonat|leito|profissionais/.test(s))add("Medir saúde e assistência");if(/água|hídr|outorga|captação|reservat/.test(s))add("Investigar água");if(/energia|aneel|ons|elétr|geração|transmiss/.test(s))add("Investigar energia");if(/diário oficial|processo|licenciamento|portaria|norma|ato público/.test(s))add("Reconstruir linha do tempo");if(/educa|escola|inep|censo escolar/.test(s))add("Investigar educação");if(!p.length)add("Contextualizar e cruzar dados");return p}
